function OverseaManageCookingListTipsNode:RefreshShow(data)
    local goodsId = MaidCoffeeUtils.GetMaidCoffeeManagerSettingVo(7).num
    ---@type MaidCoffeeComponent
    local maidCoffeeComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.MaidCoffeeComponent)
    ---@type GoodsVo
    local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(goodsId)
    for i = 1, #data.sale do
        local icon = self["ImgGoodsIcon"..i]
        local price = self["TextNumber"..i]
        if not isNull(icon) then
            CfUtils.FillImage(icon,goodsVo.photoPath)
        end

        if not isNull(price) then
            CfUtils.FillText(price,data:GetPrice(i))
        end
    end
end

